select 1 as "exists" from "field" as "f" inner join "table_meta" as "t" on "t"."id" = "f"."table_id" where "t"."base_id" = $1 and "f"."deleted_time" is null and COALESCE("f"."is_pending", false) = false and "t"."deleted_time" is null and (
    "t"."provision_state" IN ($2, $3)
    OR (
      "t"."id" IN ($4)
