  ) and ("f"."is_lookup" = $5 or "f"."is_conditional_lookup" = $6 or "f"."type" in ($7, $8, $9, $10, $11, $12) or (
                  f.is_computed = true
                  AND f.type NOT IN ($13, $14, $15, $16, $17)
